import{_ as o,o as t,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writing-view/report3_spec.md","filePath":"feature/content-task-workflow/3-6-10-content-writing-view/report3_spec.md"}'),c={name:"feature/content-task-workflow/3-6-10-content-writing-view/report3_spec.md"};function a(s,e,r,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[i("<p><strong>3.6.10 Content Writing View</strong></p><p><strong>Function Trigger</strong></p><p>A <code>Creator</code>, <code>Manager</code>, or <code>Owner</code> opens the Content Writing View from a Post Task Detail screen or navigates to <code>/workspaces/{id}/content-writing</code>.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: <code>Owner, Manager, Creator, Client</code></li><li><strong>Purpose</strong>: Allow workspace members to compose, format, import/export, and preview social media post content using a pixel-accurate Google Docs / Microsoft Word canvas editor, automatically converting chosen fonts and text effects into platform-compatible Unicode characters (YayText / Zantext standard) for both <strong>direct API auto-publishing</strong> (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>) and <strong>manual 1-click copy-paste</strong> into standard social posts, while maintaining an append-only version history and real-time multi-user collaboration.</li><li><strong>Interface</strong>: Google Docs / Word hybrid canvas editor (<code>816px</code> page sheet, ruler, zoom controls, Docs/Ribbon toolbar switcher, YayText/Zantext 36-style font converter popover, Google Docs/File import modal, AI Caption assistant with Brand Knowledge status, 4-platform live social preview with plain-text Facebook paste sandbox, and Version History sidebar).</li><li><strong>Data Processing</strong>: Every edit is recorded as an append-only Yjs CRDT operation (<code>TaskContentOperation</code>) and periodically checkpointed into a <code>TaskContentSnapshot</code>. Concurrent edits and live cursor awareness from multiple users are synchronized in real time over STOMP WebSocket (<code>/ws/tasks</code>). When copying or publishing, the formatting engine (<code>toPublishText</code> / <code>styleRunText</code>) converts rich-text runs into Unicode Mathematical Alphanumeric Symbols, Enclosed Alphanumerics (<code>🅑🅤🅑🅑🅛🅔</code>, <code>🅱🅻🅰🅲🅺</code>, <code>ⒶⒷⒸ</code>, <code>🄰🄱🄲</code>), and Combining Overlays (<code>\\u0332</code>, <code>\\u0333</code>, <code>\\u0336</code>, <code>\\u0338</code>) with smart Vietnamese diacritic handling.</li></ul><p><strong>Screen Layout</strong></p><p><em>Figure 72 - Content Writing View</em></p><ul><li>Canvas-rendered document sheet (<code>&lt;canvas&gt;</code>) with pixel-accurate caret and selection rendering, paired with an off-screen Vietnamese IME-aware input layer.</li><li>Formatting toolbar supporting Google Docs compact mode and Microsoft Word Ribbon mode, 16+ font families, YayText/Zantext 36-style quick converter (<code>Font Zantext</code>), Document Import (<code>Nhập Google Docs / File</code>), Document Export (<code>.docx</code>, <code>.md</code>, <code>.txt</code>), and AI Caption generation (<code>Có BK</code> / <code>Không BK</code>).</li><li>4-platform Live Social Preview (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>) with 1-click Unicode Copy (<code>Copy dán Facebook (Giữ Font)</code>), Plain-Text Facebook Composer Sandbox (<code>Thử dán FB</code>), and Direct API Publish modal (<code>Đăng bài</code>).</li><li>Version History sidebar listing snapshots with author name, timestamp, word-level diff (<code>Changes</code>), and 1-click restore (<code>Restore</code>).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Workspace identifier (<code>workspaceId</code>), Task identifier (<code>taskId</code>), and Yjs CRDT operation updates or imported document content.</li><li><strong>Input optional</strong>: Target social platforms (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>), selected Unicode font/effect preset, Google Docs share URL or uploaded file (<code>.docx</code>, <code>.txt</code>, <code>.md</code>, <code>.html</code>), AI Caption prompt.</li><li><strong>System data</strong>: Task record (type <code>POST</code>), workspace membership &amp; role permissions, append-only operation log (<code>task_content_operations</code>), periodic snapshots (<code>task_content_snapshots</code>), connected social accounts, and workspace Brand Knowledge status.</li><li><strong>Output</strong>: Real-time synchronized canvas document, Unicode-converted social post text (<code>publishText</code>) copied to system clipboard or published via API to connected social platforms, and restorable version snapshots.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li>Only a Task of type <code>POST</code> supports the Content Writing View.</li><li><code>Owner</code>, <code>Manager</code>, and <code>Creator</code> roles may edit, import, copy, and publish content; <code>Client</code> role may view shared content according to workspace permissions.</li><li>Every edit is persisted as an append-only operation; restoring an earlier version applies the historical state as a new forward operation so no history is overwritten.</li><li>All chosen fonts, bold/italic/underline/strikethrough marks, price slashes, and bullet/numbered lists are automatically converted to Unicode characters upon clipboard copy (<code>Ctrl+C</code> or 1-click Copy buttons) and upon API publishing to <code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, and <code>Threads</code>.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Task does not exist or belongs to another workspace → Display not-found notification (<code>MSG04</code>).</li><li>Task is not of type <code>POST</code> → Display validation notification (<code>MSG12</code>).</li><li>Google Docs import URL is malformed or not publicly shared → Display actionable guidance prompting the user to enable link sharing or upload a <code>.docx</code> file.</li><li>Empty document → Disable <code>Sao chép bản đăng</code>, <code>Copy dán Facebook (Giữ Font)</code>, and <code>Đăng bài</code> actions until content is entered.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens the Content Writing View for a Post task.</li><li>The system loads the latest content snapshot and tail operations, renders the canvas page, and establishes a real-time WebSocket session (including live peer cursor awareness).</li><li>The user types content directly, imports a Google Docs link / <code>.docx</code> file, or generates an AI Caption (<code>Có BK</code> / <code>Không BK</code>), and applies fonts or YayText/Zantext Unicode styles.</li><li>The system renders the styled text on the canvas, updates the 4-platform Live Social Preview in real time, and streams CRDT operations to connected peers.</li><li>The user either (a) clicks <code>Copy dán Facebook (Giữ Font)</code> / presses <code>Ctrl+C</code> to copy the Unicode-formatted post for manual pasting onto Facebook, or (b) clicks <code>Đăng bài</code> to auto-publish the formatted post directly to selected social platforms (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code>).</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: The backend server or WebSocket connection is temporarily unreachable. 2.a2: The system switches to Offline Mode (<code>Chế độ Ngoại tuyến</code>), queuing edits in local storage and resynchronizing automatically upon reconnection.</li><li>3.a1: The user imports an unsupported file extension or a private Google Docs link. 3.a2: The system displays a clear validation message and keeps the existing document unchanged.</li><li>5.a1: A target social platform account is not yet connected during Direct API Publish. 5.a2: The system prompts the user to connect the account or use the 1-click <code>Copy dán Facebook</code> button to post manually.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>New CRDT operations and periodic snapshots are saved to the task&#39;s content history, and the Unicode-formatted social post is either copied to the user&#39;s clipboard or published to the selected social media platforms.</li></ul>",14)])])}const m=o(c,[["render",a]]);export{g as __pageData,m as default};
